window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-eaa1acf60f4e5d7a"]={"versions": [{"id": "FIG-eaa1acf60f4e5d7a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsmodusverhaltens (Transmission Mode, TM) im AUTOSAR Communication Modul (COM). Das Diagramm stellt das Zusammenwirken der Übertragungsmodi Periodic und Direct/N-Times mit Transmission Mode Selection (TMS) und Mindestsendeabstand (Minimum Delay Time, MDT / dt) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitstrahl t: Diskrete zeitliche Achse der Sendeereignisse und Moduswechsel.\n</li><li>Grüne vertikale Pfeile (nach unten zeigend auf die Zeitachse): Ausgelöste PDU-Sendezeitpunkte (Transmission Requests) von COM an die unterlagerte Schicht (PDU Router).\n</li><li>Rote Blitze: Moduswechsel- bzw. Sendeanforderungstrigger (z. B. durch RTE/SWC via <code>Com_SendSignal</code> ausgelöster TMS-Wechsel oder Ereignistrigger).\n</li><li>Doppelpfeile mit Beschriftung:\n<ul class=\"fig-list\"><li>t_c: Zykluszeit des periodischen Sendemodus (Periodic Transmission).\n</li><li>t_d: Zykluszeit bzw. Wiederholabstand der N-fachen Sofortübertragung (Direct/N-Times Transmission).\n</li><li>dt: Mindestsendeabstand (Minimum Delay Time, MDT) zur Begrenzung der Buslast.\n</li><li>&gt;dt: Verstreichen einer Zeitspanne größer als die Mindestverzögerungszeit dt.\n</li><li>Intervall t mit roten gestrichelten Begrenzungslinien: Kurze Zeitverzögerung bzw. Filterzeit am Moduswechsel.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Periodischer Betrieb: COM befindet sich im periodischen Sendemodus und sendet PDUs in festen Intervallen der Dauer t_c.\n</li><li>Umschaltung auf Direct/N-Times: Ein Trigger (roter Blitz) initiiert einen Moduswechsel (TMS switch) auf Direct/N-Times mit n = 3. Das erste Sendeereignis wird verzögert, bis der Mindestsendeabstand dt seit dem vorangegangenen periodischen Sendezeitpunkt abgelaufen ist.\n</li><li>Burst-Aussendung: Es folgen n = 3 Übertragungen im Wiederholabstand t_d (sofern dt gewahrt bleibt).\n</li><li>Weiterer Trigger: Ein erneuter Trigger löst eine weitere Folge von Übertragungen im Abstand t_d aus.\n</li><li>Rückkehr zum periodischen Modus: Nach Ablauf einer Pause größer als dt (&gt;dt) schaltet COM wieder in den periodischen Modus um (angedeutet durch den Blitz an der Intervallgrenze t). Die Aussendung erfolgt anschließend wieder zyklisch mit der Periode t_c.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient Entwicklern zur korrekten Konfiguration und Implementierung von TMS-Wechseln und gemischten Übertragungsmodi (Mixed Transmission Modes) gemäß AUTOSAR COM:</p>\n<ul class=\"fig-list\"><li>Die konfigurierte Minimum Delay Time (dt / <code>ComMinimumDelayTime</code>) hat stets Vorrang und blockiert vorzeitige Sendeanforderungen, auch wenn durch Moduswechsel oder Direct-Trigger eine sofortige Übertragung angefordert wird.\n</li><li>Bei N-Times-Aussendungen (n = 3) ist der zeitliche Abstand zwischen den Wiederholungen (t_d / <code>ComTxModeNumberOfRepetitionsFactor</code> / <code>ComTxModeRepetitionPeriod</code>) einzuhalten.\n</li><li>Nach Abschluss der ereignisgesteuerten N-fachen Wiederholungen wird das periodische Zeitraster (t_c / <code>ComTxModeTimePeriodFactor</code>) basierend auf den Moduswechsel-Bedingungen nahtlos fortgesetzt.\n</li></ul>"}, {"id": "FIG-3a69af5afe00f8a6", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsmodusverhaltens (Transmission Mode, TM) im AUTOSAR Communication Modul (COM). Das Diagramm stellt das Zusammenwirken der Übertragungsmodi Periodic und Direct/N-Times mit Transmission Mode Selection (TMS) und Mindestsendeabstand (Minimum Delay Time, MDT / dt) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitstrahl t: Diskrete zeitliche Achse der Sendeereignisse und Moduswechsel.\n</li><li>Grüne vertikale Pfeile (nach unten zeigend auf die Zeitachse): Ausgelöste PDU-Sendezeitpunkte (Transmission Requests) von COM an die unterlagerte Schicht (PDU Router).\n</li><li>Rote Blitze: Moduswechsel- bzw. Sendeanforderungstrigger (z. B. durch RTE/SWC via <code>Com_SendSignal</code> ausgelöster TMS-Wechsel oder Ereignistrigger).\n</li><li>Doppelpfeile mit Beschriftung:\n<ul class=\"fig-list\"><li>t_c: Zykluszeit des periodischen Sendemodus (Periodic Transmission).\n</li><li>t_d: Zykluszeit bzw. Wiederholabstand der N-fachen Sofortübertragung (Direct/N-Times Transmission).\n</li><li>dt: Mindestsendeabstand (Minimum Delay Time, MDT) zur Begrenzung der Buslast.\n</li><li>&gt;dt: Verstreichen einer Zeitspanne größer als die Mindestverzögerungszeit dt.\n</li><li>Intervall t mit roten gestrichelten Begrenzungslinien: Kurze Zeitverzögerung bzw. Filterzeit am Moduswechsel.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Periodischer Betrieb: COM befindet sich im periodischen Sendemodus und sendet PDUs in festen Intervallen der Dauer t_c.\n</li><li>Umschaltung auf Direct/N-Times: Ein Trigger (roter Blitz) initiiert einen Moduswechsel (TMS switch) auf Direct/N-Times mit n = 3. Das erste Sendeereignis wird verzögert, bis der Mindestsendeabstand dt seit dem vorangegangenen periodischen Sendezeitpunkt abgelaufen ist.\n</li><li>Burst-Aussendung: Es folgen n = 3 Übertragungen im Wiederholabstand t_d (sofern dt gewahrt bleibt).\n</li><li>Weiterer Trigger: Ein erneuter Trigger löst eine weitere Folge von Übertragungen im Abstand t_d aus.\n</li><li>Rückkehr zum periodischen Modus: Nach Ablauf einer Pause größer als dt (&gt;dt) schaltet COM wieder in den periodischen Modus um (angedeutet durch den Blitz an der Intervallgrenze t). Die Aussendung erfolgt anschließend wieder zyklisch mit der Periode t_c.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient Entwicklern zur korrekten Konfiguration und Implementierung von TMS-Wechseln und gemischten Übertragungsmodi (Mixed Transmission Modes) gemäß AUTOSAR COM:</p>\n<ul class=\"fig-list\"><li>Die konfigurierte Minimum Delay Time (dt / <code>ComMinimumDelayTime</code>) hat stets Vorrang und blockiert vorzeitige Sendeanforderungen, auch wenn durch Moduswechsel oder Direct-Trigger eine sofortige Übertragung angefordert wird.\n</li><li>Bei N-Times-Aussendungen (n = 3) ist der zeitliche Abstand zwischen den Wiederholungen (t_d / <code>ComTxModeNumberOfRepetitionsFactor</code> / <code>ComTxModeRepetitionPeriod</code>) einzuhalten.\n</li><li>Nach Abschluss der ereignisgesteuerten N-fachen Wiederholungen wird das periodische Zeitraster (t_c / <code>ComTxModeTimePeriodFactor</code>) basierend auf den Moduswechsel-Bedingungen nahtlos fortgesetzt.\n</li></ul>"}], "trans": [{"from": "FIG-eaa1acf60f4e5d7a", "to": "FIG-3a69af5afe00f8a6", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
